import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };

test('unknown run and duplicate start', async () => {
  const h = await createHost();
  assert.equal(await h.run('x'), null);
  assert.equal((await h.taskStarted('x', 0)).ok, false);
  assert.equal((await h.cancel('x')).ok, false);
  assert.equal(await h.run('x'), null);
  assert.deepEqual(await h.start('a'), ok);
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('bad task numbers and moves', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [3, -1, 1.5]) assert.equal((await h.taskStarted('a', t)).ok, false);
  assert.equal((await h.taskCompleted('a', 0)).ok, false);
  assert.equal((await h.taskRequeued('a', 0)).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('completes only when all complete; then refuses', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) assert.deepEqual(await h.taskStarted('a', t), ok);
  assert.equal((await h.run('a')).status, 'running');
  await h.taskCompleted('a', 0);
  await h.taskCompleted('a', 1);
  assert.equal((await h.run('a')).status, 'running');
  await h.taskCompleted('a', 2);
  assert.equal((await h.run('a')).status, 'completed');
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.start('a')).ok, false);
});

test('evicted all, requeue, fail', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskEvicted('a', t); }
  assert.equal((await h.run('a')).status, 'evicted');
  await h.taskRequeued('a', 0);
  assert.equal((await h.run('a')).status, 'running');
  await h.taskRequeued('a', 1);
  await h.taskRequeued('a', 2);
  assert.equal((await h.run('a')).status, 'queued');
  await h.taskStarted('a', 1);
  await h.taskFailed('a', 1);
  assert.deepEqual(await h.run('a'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued' });
  assert.equal((await h.taskStarted('a', 0)).ok, false);
});

test('cancel with a completed task', async () => {
  const h = await createHost();
  await h.start('a');
  await h.taskStarted('a', 0);
  await h.taskCompleted('a', 0);
  await h.taskStarted('a', 1);
  await h.taskEvicted('a', 1);
  assert.deepEqual(await h.cancel('a'), ok);
  assert.deepEqual(await h.run('a'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.cancel('a')).ok, false);
  await h.start('b');
  assert.deepEqual(await h.cancel('b'), ok);
  assert.equal((await h.run('b')).status, 'cancelled');
});

