test('retry a failed task', async () => {
  const h = await createHost();
  await h.start('a');
  assert.equal((await h.taskRetried('a', 0)).ok, false);
  await h.taskStarted('a', 0);
  await h.taskFailed('a', 0);
  assert.equal((await h.taskRetried('a', 3)).ok, false);
  assert.deepEqual(await h.taskRetried('a', 0), ok);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskFailed('a', t); }
  assert.equal((await h.run('a')).status, 'failed');
  assert.equal((await h.cancel('a')).ok, false);
  await h.taskRetried('a', 1);
  assert.deepEqual(await h.cancel('a'), ok);
  assert.deepEqual(await h.run('a'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'failed' });
  await h.taskRetried('a', 0);
  assert.equal((await h.run('a')).status, 'failed');
  await h.taskRetried('a', 2);
  assert.equal((await h.run('a')).status, 'running');
  await h.cancel('a');
  assert.equal((await h.run('a')).status, 'cancelled');
  assert.equal((await h.taskRetried('a', 0)).ok, false);
});

