import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };

test('unknown run and duplicate start', async () => {
  const h = await createHost();
  assert.equal(await h.run('x'), null);
  assert.equal((await h.taskStarted('x', 0)).ok, false);
  assert.equal((await h.cancel('x')).ok, false);
  assert.equal(await h.run('x'), null);
  assert.deepEqual(await h.start('a'), ok);
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('bad task numbers and moves', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [3, -1, 1.5]) assert.equal((await h.taskStarted('a', t)).ok, false);
  assert.equal((await h.taskCompleted('a', 0)).ok, false);
  assert.equal((await h.taskRequeued('a', 0)).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('completes only when all complete; then refuses', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) assert.deepEqual(await h.taskStarted('a', t), ok);
  assert.equal((await h.run('a')).status, 'running');
  await h.taskCompleted('a', 0);
  await h.taskCompleted('a', 1);
  assert.equal((await h.run('a')).status, 'running');
  await h.taskCompleted('a', 2);
  assert.equal((await h.run('a')).status, 'completed');
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.start('a')).ok, false);
});

test('evicted all, requeue, fail', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskEvicted('a', t); }
  assert.equal((await h.run('a')).status, 'evicted');
  await h.taskRequeued('a', 0);
  assert.equal((await h.run('a')).status, 'running');
  await h.taskRequeued('a', 1);
  await h.taskRequeued('a', 2);
  assert.equal((await h.run('a')).status, 'queued');
  await h.taskStarted('a', 1);
  await h.taskFailed('a', 1);
  assert.deepEqual(await h.run('a'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued' });
  assert.deepEqual(await h.taskStarted('a', 0), ok);
  assert.equal((await h.run('a')).status, 'failed');
});

test('retry a failed task', async () => {
  const h = await createHost();
  await h.start('a');
  assert.equal((await h.taskRetried('a', 0)).ok, false);
  await h.taskStarted('a', 0);
  await h.taskFailed('a', 0);
  assert.equal((await h.taskRetried('a', 3)).ok, false);
  assert.deepEqual(await h.taskRetried('a', 0), ok);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskFailed('a', t); }
  assert.equal((await h.run('a')).status, 'failed');
  assert.equal((await h.cancel('a')).ok, false);
  await h.taskRetried('a', 1);
  assert.deepEqual(await h.cancel('a'), ok);
  assert.deepEqual(await h.run('a'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'failed' });
  await h.taskRetried('a', 0);
  assert.equal((await h.run('a')).status, 'failed');
  await h.taskRetried('a', 2);
  assert.equal((await h.run('a')).status, 'running');
  await h.cancel('a');
  assert.equal((await h.run('a')).status, 'cancelled');
  assert.equal((await h.taskRetried('a', 0)).ok, false);
});

test('failed then completes after retry', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1]) { await h.taskStarted('a', t); await h.taskCompleted('a', t); }
  await h.taskStarted('a', 2);
  await h.taskFailed('a', 2);
  assert.equal((await h.run('a')).status, 'failed');
  await h.taskRetried('a', 2);
  assert.equal((await h.run('a')).status, 'running');
  await h.taskStarted('a', 2);
  await h.taskCompleted('a', 2);
  assert.equal((await h.run('a')).status, 'completed');
});

test('cancel one task', async () => {
  const h = await createHost();
  await h.start('a');
  assert.equal((await h.cancelTask('a', 3)).ok, false);
  assert.deepEqual(await h.cancelTask('a', 0), ok);
  assert.deepEqual(await h.run('a'), { status: 'running', task0: 'cancelled', task1: 'queued', task2: 'queued' });
  assert.equal((await h.cancelTask('a', 0)).ok, false);
  await h.taskStarted('a', 1);
  await h.taskCompleted('a', 1);
  await h.taskStarted('a', 2);
  await h.taskEvicted('a', 2);
  assert.deepEqual(await h.cancelTask('a', 2), ok);
  assert.deepEqual(await h.run('a'), { status: 'cancelled', task0: 'cancelled', task1: 'completed', task2: 'cancelled' });
  assert.equal((await h.cancelTask('a', 1)).ok, false);

  await h.start('b');
  await h.taskStarted('b', 0);
  await h.taskFailed('b', 0);
  await h.cancelTask('b', 1);
  assert.equal((await h.run('b')).status, 'failed');
  await h.cancelTask('b', 2);
  assert.equal((await h.run('b')).status, 'failed');
  await h.taskRetried('b', 0);
  assert.equal((await h.run('b')).status, 'running');
  await h.cancelTask('b', 0);
  assert.deepEqual(await h.run('b'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.taskStarted('b', 0)).ok, false);

  await h.start('c');
  await h.cancelTask('c', 0);
  for (const t of [1, 2]) { await h.taskStarted('c', t); await h.taskCompleted('c', t); }
  assert.equal((await h.run('c')).status, 'cancelled');
});

test('cancel with a completed task', async () => {
  const h = await createHost();
  await h.start('a');
  await h.taskStarted('a', 0);
  await h.taskCompleted('a', 0);
  await h.taskStarted('a', 1);
  await h.taskEvicted('a', 1);
  assert.deepEqual(await h.cancel('a'), ok);
  assert.deepEqual(await h.run('a'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.cancel('a')).ok, false);
  await h.start('b');
  assert.deepEqual(await h.cancel('b'), ok);
  assert.equal((await h.run('b')).status, 'cancelled');
});

